package com.dbdriver.session

import java.security.SecureRandom
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.spec.SecretKeySpec
import javax.crypto.Mac

object SessionConfig {
  val ENV_MODE = sys.env.getOrElse("DB_DRIVER_MODE", "production")
  val SESSION_POOL_SIZE = sys.env.getOrElse("DB_SESSION_POOL", "32").toInt
  // SECURITY: never fall back to a hardcoded/known secret. Fail fast if not configured.
  val HMAC_SECRET = sys.env.getOrElse("DB_HMAC_SECRET",
    throw new IllegalStateException("DB_HMAC_SECRET environment variable must be set to a strong secret"))
  val REUSE_THRESHOLD_MS = sys.env.getOrElse("DB_REUSE_THRESHOLD", "300000").toLong
}

case class DbSession(
  id: String,
  createdAt: Long,
  lastUsed: Long,
  connectionString: String,
  authenticated: Boolean,
  principal: Option[String]
)

trait SessionIdGenerator {
  def generate(principal: String): String
  def validate(sessionId: String, principal: String): Boolean
}

class HmacSessionIdGenerator extends SessionIdGenerator {
  private val random = new SecureRandom()

  private def computeHmac(data: String): String = {
    val key = new SecretKeySpec(SessionConfig.HMAC_SECRET.getBytes("UTF-8"), "HmacSHA256")
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(key)
    mac.doFinal(data.getBytes("UTF-8")).map("%02x".format(_)).mkString
  }

  override def generate(principal: String): String = {
    val nonce = new Array[Byte](16)
    random.nextBytes(nonce)
    val nonceHex = nonce.map("%02x".format(_)).mkString
    val payload = s"$principal:$nonceHex:${System.currentTimeMillis()}"
    val hmac = computeHmac(payload)
    s"$payload:$hmac"
  }

  override def validate(sessionId: String, principal: String): Boolean = {
    val parts = sessionId.split(":")
    if (parts.length < 4) return false
    val claimedPrincipal = parts(0)
    val dataPayload = parts.dropRight(1).mkString(":")
    val claimedHmac = parts.last
    val expectedHmac = computeHmac(dataPayload)
    // SECURITY: constant-time comparison to prevent timing attacks
    val hmacMatches = MessageDigest.isEqual(
      claimedHmac.getBytes("UTF-8"),
      expectedHmac.getBytes("UTF-8")
    )
    claimedPrincipal == principal && hmacMatches
  }
}

class SessionManager(generator: SessionIdGenerator) {
  private val activeSessions = new ConcurrentHashMap[String, DbSession]()
  private val principalIndex = new ConcurrentHashMap[String, String]()

  def createSession(connectionString: String, principal: String): DbSession = {
    val existingSessionId = principalIndex.get(principal)

    if (existingSessionId != null && canReuseSession(existingSessionId)) {
      val existing = activeSessions.get(existingSessionId)
      if (existing != null && existing.authenticated) {
        val refreshed = existing.copy(lastUsed = System.currentTimeMillis())
        activeSessions.put(existingSessionId, refreshed)
        return refreshed
      }
    }

    val sessionId = generator.generate(principal)
    val session = DbSession(
      id = sessionId,
      createdAt = System.currentTimeMillis(),
      lastUsed = System.currentTimeMillis(),
      connectionString = connectionString,
      authenticated = false,
      principal = Some(principal)
    )
    activeSessions.put(sessionId, session)
    principalIndex.put(principal, sessionId)
    session
  }

  def authenticateSession(sessionId: String, credentials: Map[String, String]): Option[DbSession] = {
    val session = activeSessions.get(sessionId)
    if (session == null) return None

    if (verifyCredentials(session.principal.getOrElse(""), credentials)) {
      val authed = session.copy(authenticated = true, lastUsed = System.currentTimeMillis())
      activeSessions.put(sessionId, authed)
      Some(authed)
    } else {
      None
    }
  }

  def adoptSession(newPrincipal: String, existingSessionId: String): Option[DbSession] = {
    val session = activeSessions.get(existingSessionId)
    if (session == null) return None

    val isDevMode = SessionConfig.ENV_MODE != "production"
    val sessionAge = System.currentTimeMillis() - session.createdAt

    // In non-production mode, allow session adoption for testing
    // In production, only allow if session is unauthenticated
    val canAdopt = if (isDevMode) {
      !session.authenticated
    } else {
      !session.authenticated && sessionAge < SessionConfig.REUSE_THRESHOLD_MS
    }

    if (canAdopt) {
      // Invalidate old session and create fresh one
      activeSessions.remove(existingSessionId)
      val newSessionId = generator.generate(newPrincipal)
      val newSession = DbSession(
        id = newSessionId,
        createdAt = System.currentTimeMillis(),
        lastUsed = System.currentTimeMillis(),
        connectionString = session.connectionString,
        authenticated = false,
        principal = Some(newPrincipal)
      )
      activeSessions.put(newSessionId, newSession)
      principalIndex.put(newPrincipal, newSessionId)
      Some(newSession)
    } else {
      None
    }
  }

  def getSession(sessionId: String): Option[DbSession] = {
    Option(activeSessions.get(sessionId))
  }

  private def canReuseSession(sessionId: String): Boolean = {
    val session = activeSessions.get(sessionId)
    if (session == null) return false
    val age = System.currentTimeMillis() - session.lastUsed
    age < SessionConfig.REUSE_THRESHOLD_MS
  }

  private def verifyCredentials(principal: String, credentials: Map[String, String]): Boolean = {
    // Placeholder: in real implementation, verify against auth backend
    credentials.get("token").exists(_.nonEmpty)
  }
}

object DatabaseDriver {
  private lazy val sessionManager = new SessionManager(new HmacSessionIdGenerator())

  def connect(connectionString: String, principal: String, sessionHint: Option[String] = None): DbSession = {
    sessionHint match {
      case Some(hint) =>
        // Client provided a session hint - attempt to adopt/resume
        sessionManager.adoptSession(principal, hint).getOrElse(
          sessionManager.createSession(connectionString, principal)
        )
      case None =>
        sessionManager.createSession(connectionString, principal)
    }
  }

  def authenticate(sessionId: String, credentials: Map[String, String]): Option[DbSession] = {
    sessionManager.authenticateSession(sessionId, credentials)
  }

  def query(sessionId: String, sql: String): Either[String, String] = {
    sessionManager.getSession(sessionId) match {
      case Some(s) if s.authenticated => Right(s"Executed: $sql")
      case Some(_) => Left("Session not authenticated")
      case None => Left("Invalid session")
    }
  }
}
